PURITY_RE = re.compile(r"(\d{1,2}(?:\.\d+)?\s*%)")
CAS_IN_NAME_RE = re.compile(r"CAS\s*号?\s*[:：]?\s*(\d{2,7}-\d{2}-\d)", re.I)
ALIAS_RE = re.compile(r"[（(]\s*([A-Za-z][A-Za-z0-9\-]{1,15})\s*[)）]\s*$")
CAS_RE = re.compile(r"^\d{2,7}-\d{2}-\d$")


# ---------------------------------------------------------------- xlsx 读取

def read_shared_strings(z):
    out = []
    with z.open("xl/sharedStrings.xml") as f:
        for _, el in ET.iterparse(f):
            if el.tag == NS + "si":
                out.append("".join(t.text or "" for t in el.iter(NS + "t")))
                el.clear()
    return out


def read_sheet(z, idx, ss):
    """返回 [(row_no, {col: value})]，只解析给定 sheet，图片不读。"""
    rows = []
    with z.open(f"xl/worksheets/sheet{idx}.xml") as f:
        for _, el in ET.iterparse(f):
            if el.tag != NS + "row":
                continue
            cells = {}
            for c in el:
                ref = c.get("r") or ""
                m = re.match(r"[A-Z]+", ref)
                if not m:
                    continue
                col = m.group(0)
                t = c.get("t")
                v = c.find(NS + "v")
                if t == "inlineStr":
                    node = c.find(NS + "is")
                    val = "".join(x.text or "" for x in node.iter(NS + "t")) if node is not None else ""
                elif v is None:
                    val = ""
                elif t == "s":
                    val = ss[int(v.text)]
                else:
                    val = v.text or ""
                if val != "":
                    cells[col] = val
            if cells:
                rows.append((int(el.get("r")), cells))
            el.clear()
    return rows


# ---------------------------------------------------------------- 清洗 / 判定

def parse_date(serial):
    try:
        n = float(serial)
    except (TypeError, ValueError):
        return ""
    if not (20000 <= n <= 80000):     # 只接受 Excel 日期序列的合理区间
        return ""
    return (datetime.date(1899, 12, 30) + datetime.timedelta(days=int(n))).isoformat()


def clean_name(raw):
    """去掉货号/规格/纯度/CAS 尾巴，抽出括号内别名。返回 (name, alias, extra_spec, cas_in_name)。"""
    s = unicodedata.normalize("NFKC", raw or "").strip()
    cas = ""
    m = CAS_IN_NAME_RE.search(s)
    if m:
        cas = m.group(1)
        s = CAS_IN_NAME_RE.sub("", s)
    alias = ""
    m = ALIAS_RE.search(s)
    if m:
        alias = m.group(1).strip()
        s = s[:m.start()].strip()
    purity = ""
    m = PURITY_RE.search(s)
    if m:
        purity = re.sub(r"\s+", "", m.group(1))
    # 去掉空的包装/纯度括号说明，如「(8包/箱）」「（12卷/箱）」
    s = re.sub(r"[（(]\s*\d+\s*(?:包|箱|盒|卷|张|只|支|个|件|袋|桶|瓶)[^）)]*[)）]\s*$", "", s)
    s = re.sub(r"^\d{5,}\s*[-—]\s*", "", s)      # 纯数字货号前缀，如 1767602- / 337986-
    s = CODE_PREFIX_RE.sub("", s)
    s = SIZE_RE.sub(" ", s)
    s = PURITY_RE.sub(" ", s)
    s = re.sub(r"[（(]\s*[)）]", "", s)          # 纯度被拿走后会留下空括号
    s = re.sub(r"\s{2,}", " ", s).strip(" -—_、,，≥≤<>")
    extra = " ".join(x for x in (purity,) if x)
    return s, alias, extra, cas


def classify(name, cas, unit):
    if any(k in name for k in CONSUMABLE_KW):
        return "耗材", "命中耗材关键词"
    if any(k in name for k in MATERIAL_KW):
        return "材料", "命中材料关键词（箔/片/极片等）"
    if cas and CAS_RE.match(cas):
        return "试剂", "有 CAS 号"
    if any(k in name for k in REAGENT_KW):
        return "试剂", "命中化学名词/元素"
    if unit in ("瓶", "桶", "支", "瓶装"):
        return "试剂", "瓶/桶装且无耗材特征（低置信）"
    return "未知", "无判定依据"


def extract(xlsx_path, sheet_indexes=(1, 2, 3)):
    z = zipfile.ZipFile(xlsx_path)
    ss = read_shared_strings(z)
    out = []
    for idx in sheet_indexes:
        if f"xl/worksheets/sheet{idx}.xml" not in z.namelist():
            continue
        for row_no, cells in read_sheet(z, idx, ss):
            name_raw = (cells.get(COL_NAME) or "").strip()
            if not name_raw or name_raw in HEADER_NAMES:
                continue
            if re.fullmatch(r"[\d.]+", name_raw):
                continue
            name, alias, extra, cas_in_name = clean_name(name_raw)
            if not name:
                continue
            cas = (cells.get(COL_CAS) or "").strip()
            if cas in ("/", "-", "—"):
                cas = ""
            cas = cas or cas_in_name
            unit = (cells.get(COL_UNIT) or "").strip()
            qty_raw = (cells.get(COL_QTY) or "").strip()
            try:
                qty = float(qty_raw)
            except ValueError:
                qty = None
            cat, reason = classify(name, cas, unit)
            spec = " | ".join(x for x in [(cells.get(COL_SPEC) or "").strip(), extra] if x)
            out.append({
                "sheet": f"sheet{idx}", "row": row_no,
                "raw_name": name_raw, "name": name, "alias": alias, "spec": spec,
                "cas": cas, "unit": unit, "qty": qty,
                "date": parse_date(cells.get(COL_DATE)),
                "voucher": (cells.get(COL_VOUCHER) or "").strip(),
                "category": cat, "reason": reason,
            })
    return out


def load_synonyms(path=None):
    """同义表 → [(中文名, 写法)]；用于给入库试剂挂 ZnCl2 / NaPF6 这类别名。"""
    import yaml
    p = path or os.path.join(K.VAULT, SYNONYM_REL)
    if not os.path.isfile(p):
        return []
    data = yaml.safe_load(open(p, encoding="utf-8")) or {}
    pairs = []
    for formula, names in data.items():
        for cn in (names or []):
            cn = str(cn).strip()
            if cn:
                pairs.append((cn, str(formula).strip()))
    return pairs


def aliases_for(name, pairs):
    """只认**完全相同**的中文名；同物异名（含水合/无水）在同义表里逐一列出。"""
    return sorted({f for cn, f in pairs if name == cn})


def merge_reagents(records, synonym_pairs=None):
    """按名称归并（同物不同规格/多次入库）。"""
    synonym_pairs = synonym_pairs or []
    agg = {}
    for r in records:
        if r["category"] != "试剂":
            continue
        k = r["name"]
        a = agg.setdefault(k, {"name": k, "aliases": set(), "specs": [], "cas": "",
                               "units": set(), "qty": 0.0, "last_in": "", "vouchers": set()})
        if r["alias"]:
            a["aliases"].add(r["alias"])
        if r["spec"] and r["spec"] not in a["specs"]:
            a["specs"].append(r["spec"])
        if r["cas"] and not a["cas"]:
            a["cas"] = r["cas"]
        if r["unit"]:
            a["units"].add(r["unit"])
        if r["qty"] is not None:
            a["qty"] += r["qty"]
        if r["date"] > a["last_in"]:
            a["last_in"] = r["date"]
        if r["voucher"]:
            a["vouchers"].add(r["voucher"])
    out = []
    for a in sorted(agg.values(), key=lambda x: x["name"]):
        a["aliases"].update(aliases_for(a["name"], synonym_pairs))
        out.append({"name": a["name"], "aliases": sorted(a["aliases"]),
                    "spec": "; ".join(a["specs"]), "cas": a["cas"],
                    "unit": "/".join(sorted(a["units"])), "qty": round(a["qty"], 3),
                    "last_in": a["last_in"], "vouchers": sorted(a["vouchers"])})
    return out


# ---------------------------------------------------------------- 输出

def write_csv(path, records):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    cols = ["类别", "名称", "别名", "规格", "CAS", "单位", "数量", "最近入库",
            "单据编号", "来源表", "行号", "判定依据"]
    with open(path, "w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f)
        w.writerow(cols)
        for r in records:
            w.writerow([r["category"], r["name"], r["alias"], r["spec"], r["cas"],
                        r["unit"], "" if r["qty"] is None else r["qty"],
                        r["date"], r["voucher"], r["sheet"], r["row"], r["reason"]])
    with open(path, encoding="utf-8-sig") as f:
        n = sum(1 for _ in f) - 1
    if n != len(records):
        raise SystemExit(f"[!] CSV 写后复算失败：{n} != {len(records)}")
    return path, n


def write_yaml(path, meta, reagents):
    import yaml
    os.makedirs(os.path.dirname(path), exist_ok=True)
    doc = {"meta": meta, "reagents": reagents}
    text = yaml.safe_dump(doc, allow_unicode=True, sort_keys=False, width=120)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    back = yaml.safe_load(open(path, encoding="utf-8"))
    if len(back.get("reagents") or []) != len(reagents):
        raise SystemExit("[!] YAML 写后复算失败")
    return path


# ---------------------------------------------------------------- 自检

def _mini_xlsx(path):
    """造一个最小 xlsx（只有 workbook/sharedStrings/sheet1），用于自检。"""
    ss = []

    def sid(s):
        ss.append(s)
        return len(ss) - 1

    rows = []
    def add(r, cells):
        xml = "".join(
            f'<c r="{col}{r}" t="s"><v>{sid(val)}</v></c>' if isinstance(val, str) else
            f'<c r="{col}{r}"><v>{val}</v></c>'
            for col, val in cells.items())
        rows.append(f'<row r="{r}">{xml}</row>')

    add(3, {"A": 46230, "B": "XS-1", "C": "D155537-500ml 氯化钙", "D": "500ml",
            "E": "10043-52-4", "G": "瓶", "H": 1})
    add(4, {"A": 46231, "B": "XS-2", "C": "A4打印纸(8包/箱）", "G": "包", "H": 2})
    add(5, {"A": 46232, "B": "XS-3", "C": "2-甲基四氢呋喃 (MeTHF)", "D": "50g",
            "G": "瓶", "H": 1})
    add(6, {"A": 46233, "B": "XT-1", "C": "氯化钙", "D": "2.5kg", "G": "瓶", "H": -1})
    add(7, {"A": "", "C": "", "H": 9})
    add(8, {"A": 46234, "B": "XS-4", "C": "氯化钙", "D": "500g", "G": "瓶", "H": 1})

    sheet = ('<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="%s"><sheetData>%s'
             '</sheetData></worksheet>') % (NS.strip("{}"), "".join(rows))
    shared = ('<?xml version="1.0" encoding="UTF-8"?><sst xmlns="%s">%s</sst>'
              % (NS.strip("{}"), "".join(f"<si><t>{s}</t></si>" for s in ss)))
    wb = ('<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="%s"><sheets>'
          '<sheet name="测试" sheetId="1"/></sheets></workbook>') % NS.strip("{}")
    with zipfile.ZipFile(path, "w") as z:
        z.writestr("xl/workbook.xml", wb)
        z.writestr("xl/sharedStrings.xml", shared)
        z.writestr("xl/worksheets/sheet1.xml", sheet)


def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    tmp = K.make_temp_dir(prefix="sci_reagent_")
    try:
        xp = os.path.join(tmp, "mini.xlsx")
        _mini_xlsx(xp)
        recs = extract(xp, sheet_indexes=(1,))
        by = {}
        for r in recs:
            by.setdefault(r["name"], []).append(r)
        chk("提取：表头行被跳过", all(r["name"] != "存货全名" for r in recs))
        chk("提取：空品名行被跳过", len(recs) == 5, str([r["name"] for r in recs]))
        chk("清洗：货号+规格前缀被去掉", "氯化钙" in by and "D155537" not in by["氯化钙"][0]["name"])
        chk("清洗：别名从括号抽出并去掉括号",
            "2-甲基四氢呋喃" in by and by["2-甲基四氢呋喃"][0]["alias"] == "MeTHF",
            str(list(by)))
        chk("判定：CAS 行 → 试剂", by["氯化钙"][0]["category"] == "试剂")
        chk("判定：打印纸 → 耗材", by["A4打印纸"][0]["category"] == "耗材")
        chk("判定：瓶装且含化学词 → 试剂", by["2-甲基四氢呋喃"][0]["category"] == "试剂")
        chk("日期：Excel 序列 → ISO", by["氯化钙"][0]["date"] == "2026-07-27")
        merged = merge_reagents(recs)
        ca = next((x for x in merged if x["name"] == "氯化钙"), None)
        chk("归并：同名不同规格合并为一条", ca is not None and len(merged) == 2,
            str([x["name"] for x in merged]))
        chk("归并：数量按有符号累加（含退货）", ca["qty"] == 1.0, str(ca and ca["qty"]))
        chk("归并：规格去重后保留三种", ca["spec"].count(";") == 2, ca["spec"])
        p_csv, n = write_csv(os.path.join(tmp, "out.csv"), recs)
        chk("输出：CSV 写后复算行数一致", n == len(recs))
        p_y = write_yaml(os.path.join(tmp, "out.yaml"),
                         {"rows": len(recs), "reagents": len(merged)}, merged)
        import yaml as _y
        back = _y.safe_load(open(p_y, encoding="utf-8"))
        chk("输出：YAML 可解析且条数一致", len(back["reagents"]) == len(merged))
        chk("隐私：CSV 列不含价格/客户", "客户" not in open(p_csv, encoding="utf-8-sig").readline()
            and "单价" not in open(p_csv, encoding="utf-8-sig").readline())
        pairs = [("四氢呋喃", "THF"), ("2-甲基四氢呋喃", "MeTHF"),
                 ("碳酸乙烯酯", "EC")]
        chk("同义：只认完全相同，不把 2-甲基四氢呋喃 认成 THF",
            aliases_for("2-甲基四氢呋喃", pairs) == ["MeTHF"]
            and aliases_for("四氢呋喃", pairs) == ["THF"])
        chk("同义：不把衍生物认成本体（4-三氟甲基碳酸乙烯酯 ≠ EC）",
            aliases_for("4-三氟甲基碳酸乙烯酯", pairs) == [])
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="试剂/耗材入库表 → 试剂清单（只读 B/C/D，忽略图片）")
    ap.add_argument("--xlsx", default=DEFAULT_XLSX)
    ap.add_argument("--out-csv", default=OUT_CSV)
    ap.add_argument("--out-yaml", default=OUT_YAML)
    ap.add_argument("--apply", action="store_true", help="写 CSV/YAML（默认干跑）")
    ap.add_argument("--json", action="store_true", help="结果 JSON 打印到 stdout")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()

    xp = args.xlsx if os.path.isabs(args.xlsx) else os.path.join(K.VAULT, args.xlsx)
    if not os.path.isfile(xp):
        raise SystemExit(f"[!] 找不到 {xp}")
    size_mb = os.path.getsize(xp) / 1048576
    recs = extract(xp)
    pairs = load_synonyms()
    merged = merge_reagents(recs, pairs)
    cats = {}
    for r in recs:
        cats[r["category"]] = cats.get(r["category"], 0) + 1
    meta = {
        "source": os.path.relpath(xp, K.VAULT).replace("\\", "/"),
        "extracted_at": datetime.date.today().isoformat(),
        "rows_scanned": len(recs),
        "by_category": cats,
        "reagents_merged": len(merged),
        "privacy": "只取 B/C/D（单号/品名/规格）+ 必要数量与 CAS；未导出价格、客户、经办人与照片",
        "note": "采购记录 ≠ 现有库存：数量为入库累计（含负数为退货），是否还有余量需人工确认",
    }
    print(f"[ok] 读取 {os.path.basename(xp)}（{size_mb:.0f} MB，仅解析 XML，未加载图片）")
    print(f"     行数 {len(recs)}   分类 {cats}   归并后试剂 {len(merged)} 条")
    sample = [r for r in recs if r["category"] != "试剂"][:5]
    for r in sample:
        print(f"     非试剂样例：{r['name']}  →  {r['category']}（{r['reason']}）")
    unknown = [r for r in recs if r["category"] == "未知"]
    for r in unknown[:10]:
        print(f"     [?] 未知：{r['name']}（单位 {r['unit']}）")
    if args.json:
        print(json.dumps({"meta": meta, "reagents": merged[:5]},
                         ensure_ascii=False, indent=2))
    if not args.apply:
        print("     （干跑；加 --apply 写 CSV/YAML）")
        return 0
    p_csv, n = write_csv(os.path.join(K.VAULT, args.out_csv), recs)
    p_y = write_yaml(os.path.join(K.VAULT, args.out_yaml), meta, merged)
    print(f"[ok] CSV：{os.path.relpath(p_csv, K.VAULT)}（{n} 行）")
    print(f"[ok] YAML：{os.path.relpath(p_y, K.VAULT)}（{len(merged)} 条试剂）")
    return 0


if __name__ == "__main__":
    sys.exit(main())
